"""Render exact animation frames of output.svg via headless Chrome."""
import os, subprocess, sys

SRC = "/tmp/free-stealth-bench-7y2mdc44/output.svg"
times = [float(t) for t in sys.argv[1:]] or [0.5]
for t in times:
