    <embed id="e" src="file://%s" type="image/svg+xml" width="1200" height="800">
    <script>
    var e=document.getElementById('e');
    e.addEventListener('load',function(){
      var svg=this.getSVGDocument();
      svg.pauseAnimations();
      svg.setCurrentTime(%r);
      document.title='ready';
    });
