                    "--virtual-time-budget=4000", "--screenshot=" + out,
                    "--window-size=1200,800", "file:///tmp/opencode/frame.html"],
                   stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    print(out, os.path.exists(out))

